INSERT INTO `formatos_impresion` (`id`, `tipo_documento`, `nombre_plantilla`, `ancho_papel_mm`, `cuerpo_html`) VALUES
(1, 'FACTURA', 'Ticket Fiscal 80mm', 80, '<!DOCTYPE html><html><head><meta charset="utf-8"><style>body{font-family:monospace;font-size:11px;width:280px;margin:0;padding:5px;}.center{text-align:center;}.right{text-align:right;}.bold{font-weight:bold;}.line{border-bottom:1px dashed #000;margin:5px 0;}table{width:100%;font-size:11px;}</style></head><body><div class="center"><span class="bold">{{empresa_nombre}}</span><br>RIF: {{empresa_rif}}<br>{{empresa_direccion}}</div><div class="line"></div><div><b>Factura N°:</b> {{numero_documento}}<br><b>Control:</b> {{control_fiscal}}<br><b>Fecha:</b> {{fecha_emision}}<br><b>Cliente:</b> {{cliente_nombre}}<br><b>RIF/CI:</b> {{cliente_rif}}</div><div class="line"></div><table><thead><tr class="bold"><td>Cant/Desc</td><td class="right">Total</td></tr></thead><tbody>{{tabla_items}}</tbody></table><div class="line"></div><table><tr><td>Subtotal:</td><td class="right">{{subtotal}} $</td></tr><tr><td>Base Imp.:</td><td class="right">{{base_imponible}} $</td></tr><tr><td>IVA (16%):</td><td class="right">{{monto_iva}} $</td></tr><tr class="bold"><td>TOTAL:</td><td class="right">{{total_general}} $</td></tr><tr class="bold"><td>TOTAL Bs:</td><td class="right">{{total_general_bs}} Bs</td></tr></table><div class="center" style="margin-top:8px;">{{qr_fiscal_img}}<br>¡Gracias por su preferencia!</div></body></html>'),
(2, 'NOTA_ENTREGA', 'Nota de Entrega Media Carta', 216, '<!DOCTYPE html><html><head><meta charset="utf-8"><style>body{font-family:sans-serif;font-size:12px;margin:20px;}.bold{font-weight:bold;}table{width:100%;border-collapse:collapse;}th,td{border:1px solid #ddd;padding:6px;}</style></head><body><h2>{{empresa_nombre}}</h2><p><b>NOTA DE ENTREGA N°:</b> {{numero_documento}} | <b>Fecha:</b> {{fecha_emision}}</p><p><b>Cliente:</b> {{cliente_nombre}} ({{cliente_rif}})</p><table><thead><tr style="background:#f1f5f9;"><th>Descripción</th><th style="text-align:right;">Cantidad</th><th style="text-align:right;">Total $</th></tr></thead><tbody>{{tabla_items}}</tbody></table><p style="text-align:right;font-size:14px;"><b>TOTAL:</b> {{total_general}} $</p></body></html>'),
(3, 'PRESUPUESTO', 'Presupuesto Carta', 216, '<!DOCTYPE html><html><head><meta charset="utf-8"><style>body{font-family:sans-serif;font-size:12px;margin:20px;}.bold{font-weight:bold;}table{width:100%;border-collapse:collapse;}th,td{border:1px solid #ddd;padding:6px;}</style></head><body><h2>{{empresa_nombre}}</h2><p><b>PRESUPUESTO / COTIZACIÓN N°:</b> {{numero_documento}} | <b>Fecha:</b> {{fecha_emision}}</p><p><b>Cliente:</b> {{cliente_nombre}} ({{cliente_rif}})</p><table><thead><tr style="background:#f1f5f9;"><th>Descripción</th><th style="text-align:right;">Cantidad</th><th style="text-align:right;">Precio Unit</th><th style="text-align:right;">Total $</th></tr></thead><tbody>{{tabla_items}}</tbody></table><p style="text-align:right;font-size:14px;"><b>TOTAL ESTIMADO:</b> {{total_general}} $</p></body></html>'),
(4, 'PEDIDO', 'Pedido de Almacén', 80, '<!DOCTYPE html><html><head><meta charset="utf-8"><style>body{font-family:monospace;font-size:11px;width:280px;margin:0;padding:5px;}.bold{font-weight:bold;}</style></head><body><div style="text-align:center;"><span class="bold">PEDIDO DE DESPACHO</span><br>{{numero_documento}}</div><hr><b>Cliente:</b> {{cliente_nombre}}<br><b>Vendedor:</b> {{vendedor_nombre}}<hr><table>{{tabla_items}}</table><hr><div style="text-align:right;"><b>Total:</b> {{total_general}} $</div></body></html>')
